//! Independent replay against the Python float64 oracle.
//!
//! Consensus §5.3: "Rust must replay committed or generated fixtures rather
//! than merely sharing code paths." Two fixtures are replayed here.
//!
//! 1. `paper/ariadne-gesture-compiler/reference/results.json` — the reference
//!    package's own experiment receipt. The copy committed before this work
//!    was **corrupt**: a hand edit had dropped a `},` inside the
//!    `exact_closed_loop_so3.named` schedule, so the file was not valid JSON
//!    and nothing could parse it. It was regenerated by
//!    `run_experiments.py` under the repo `.venv` and re-committed. The
//!    regeneration is a `full` run, matching the mode of the artifact it
//!    replaces (the spec asked for at least `--quick`). This test parses it
//!    and checks the exact-compiler invariants it claims. It carries
//!    aggregates only — no per-target schedules — which is why the second
//!    fixture exists.
//!
//! 2. `fixtures/tree_qr_oracle.json` — generated by
//!    `fixtures/gen_tree_qr_oracle.py`, which drives the same oracle and dumps
//!    graph, tree, leaf order, target, schedule, and timing per case. Rust
//!    then does three independent things with it:
//!
//!    * **executes the Python word** through `mus_watsn::OperatorProgram` and
//!      checks it reaches the Python target;
//!    * **recompiles** from the same tree and leaf order and checks the gate
//!      planes agree exactly and the angles agree numerically;
//!    * **re-times** the word and checks the thermodynamic length, predicted
//!      cost, and segment durations agree.

use std::path::{Path, PathBuf};

use mus_gesture::{
    compile, compile_on_tree, endpoint_operator, thermodynamic_schedule, ControlGraph, EdgeControl,
    EdgeId, FrictionMetric, LeafOrder, Matrix, ModeId, RotationTarget, SpanningTree,
};
use mus_watsn::OperatorProgram;
use serde::Deserialize;

fn repository_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(3)
        .expect("crate lives at <repo>/mus-rs/crates/mus-gesture")
        .to_path_buf()
}

// ---------------------------------------------------------------------
// Fixture 1: the reference package's own experiment receipt.
// ---------------------------------------------------------------------

#[derive(Debug, Deserialize)]
struct ReferenceResults {
    schema: String,
    mode: String,
    exact_edge_compiler: ExactEdgeCompiler,
    weighted_tree_search: WeightedTreeSearch,
}

#[derive(Debug, Deserialize)]
struct ExactEdgeCompiler {
    trials: usize,
    max_reconstruction_error_fro: f64,
    max_orthogonality_error_fro: f64,
    max_determinant_error: f64,
    gate_count_mismatches: usize,
    rotation_lie_rank_mismatches: usize,
    disconnected_rank_mismatches: usize,
    by_dimension: std::collections::BTreeMap<String, ByDimension>,
}

#[derive(Debug, Deserialize)]
struct ByDimension {
    trials: usize,
    gate_count: usize,
    max_reconstruction_error_fro: f64,
}

#[derive(Debug, Deserialize)]
struct WeightedTreeSearch {
    candidates: usize,
    baseline_minimum_quadratic_cost: f64,
    best_minimum_quadratic_cost: f64,
    improvement_fraction: f64,
    best_reconstruction_error_fro: f64,
}

#[test]
fn the_regenerated_reference_receipt_parses_and_holds_its_invariants() {
    let path = repository_root().join("paper/ariadne-gesture-compiler/reference/results.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
    let results: ReferenceResults = serde_json::from_str(&text)
        .unwrap_or_else(|error| panic!("{} is not valid JSON: {error}", path.display()));

    assert_eq!(results.schema, "ariadne-inverse-geometry/2");
    assert!(results.mode == "quick" || results.mode == "full");

    let exact = &results.exact_edge_compiler;
    assert_eq!(exact.gate_count_mismatches, 0);
    assert_eq!(exact.rotation_lie_rank_mismatches, 0);
    assert_eq!(exact.disconnected_rank_mismatches, 0);
    assert!(exact.max_reconstruction_error_fro < 1.0e-11);
    assert!(exact.max_orthogonality_error_fro < 1.0e-11);
    assert!(exact.max_determinant_error < 1.0e-11);
    assert!(exact.trials > 0);

    let mut counted = 0usize;
    for (dimension, entry) in &exact.by_dimension {
        let n: usize = dimension.parse().unwrap();
        assert_eq!(
            entry.gate_count,
            n * (n - 1) / 2,
            "dimension {n} claims {} gates",
            entry.gate_count
        );
        assert!(entry.max_reconstruction_error_fro < 1.0e-11);
        counted += entry.trials;
    }
    assert_eq!(counted, exact.trials);

    // The reference's own weighted-tree search is monotone too.
    let search = &results.weighted_tree_search;
    assert!(search.candidates > 0);
    assert!(search.best_minimum_quadratic_cost <= search.baseline_minimum_quadratic_cost);
    assert!(search.improvement_fraction >= 0.0);
    assert!(search.best_reconstruction_error_fro < 1.0e-11);
}

// ---------------------------------------------------------------------
// Fixture 2: per-case tree-QR replay.
// ---------------------------------------------------------------------

#[derive(Debug, Deserialize)]
struct OracleFixture {
    schema: String,
    case_count: usize,
    cases: Vec<OracleCase>,
}

#[derive(Debug, Deserialize)]
struct OracleCase {
    name: String,
    family: String,
    n: usize,
    graph_edges: Vec<[usize; 2]>,
    edge_friction: Vec<(usize, usize, f64)>,
    tree_edges: Vec<[usize; 2]>,
    leaf_order: Vec<usize>,
    target: Vec<Vec<f64>>,
    gate_count: usize,
    schedule: Vec<OracleGate>,
    reconstruction_error_fro: f64,
    orthogonality_error_fro: f64,
    determinant_error: f64,
    duration: f64,
    thermodynamic_length: f64,
    minimum_quadratic_cost: f64,
    segment_durations: Vec<f64>,
    constant_speed_residual: f64,
}

#[derive(Debug, Deserialize)]
struct OracleGate {
    i: usize,
    j: usize,
    theta: f64,
}

fn load_fixture() -> OracleFixture {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/tree_qr_oracle.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
    serde_json::from_str(&text)
        .unwrap_or_else(|error| panic!("{} is not valid JSON: {error}", path.display()))
}

fn graph_of(case: &OracleCase) -> ControlGraph {
    let modes: Vec<ModeId> = (0..case.n as u32).map(ModeId).collect();
    let edges: Vec<EdgeControl> = case
        .edge_friction
        .iter()
        .enumerate()
        .map(|(index, &(left, right, friction))| {
            EdgeControl::with_friction(
                EdgeId(index as u32),
                ModeId(left as u32),
                ModeId(right as u32),
                friction,
            )
        })
        .collect();
    assert_eq!(
        case.edge_friction.len(),
        case.graph_edges.len(),
        "{}: friction and edge lists disagree",
        case.name
    );
    for (authored, &[left, right]) in case.edge_friction.iter().zip(case.graph_edges.iter()) {
        assert_eq!((authored.0, authored.1), (left, right));
    }
    ControlGraph::new(modes, edges).unwrap()
}

#[test]
fn the_oracle_fixture_covers_the_gate_range() {
    let fixture = load_fixture();
    assert_eq!(fixture.schema, "mus-gesture/tree-qr-oracle/1");
    assert_eq!(fixture.case_count, fixture.cases.len());
    let mut dimensions: Vec<usize> = fixture.cases.iter().map(|case| case.n).collect();
    dimensions.sort_unstable();
    dimensions.dedup();
    assert_eq!(dimensions.first().copied(), Some(2));
    assert_eq!(dimensions.last().copied(), Some(32));
    assert_eq!(dimensions.len(), 31);

    let mut families: Vec<&str> = fixture
        .cases
        .iter()
        .map(|case| case.family.as_str())
        .collect();
    families.sort_unstable();
    families.dedup();
    assert_eq!(
        families,
        vec![
            "balanced_tree",
            "complete",
            "path",
            "random_connected",
            "star"
        ]
    );
}

/// Rust executes the Python word and lands on the Python target.
#[test]
fn rust_executes_the_python_schedule_onto_the_python_target() {
    let fixture = load_fixture();
    let mut worst = 0.0_f64;
    let mut worst_case = String::new();
    let mut worst_agreement = 0.0_f64;
    for case in &fixture.cases {
        let target = Matrix::from_rows(case.target.clone()).unwrap();
        let program = OperatorProgram::new(
            case.n,
            case.schedule
                .iter()
                .map(|gate| mus_watsn::PlaneRotation {
                    left: gate.i,
                    right: gate.j,
                    angle: gate.theta,
                })
                .collect(),
        )
        .unwrap();
        let endpoint = endpoint_operator(&program).unwrap();
        let error = endpoint.frobenius_distance(&target);
        assert!(
            error < 1.0e-11,
            "{}: executing the oracle word missed by {error:e}",
            case.name
        );
        if error > worst {
            worst = error;
            worst_case = case.name.clone();
        }
        // And it agrees with the error the oracle reported for itself.
        worst_agreement = worst_agreement.max((error - case.reconstruction_error_fro).abs());
        assert!(case.reconstruction_error_fro < 1.0e-11);
        assert!(case.orthogonality_error_fro < 1.0e-11);
        assert!(case.determinant_error < 1.0e-11);
    }
    println!(
        "python-word replay: worst {worst:e} ({worst_case}); \
         worst error-agreement {worst_agreement:e}"
    );
}

/// Rust recompiles the same target on the same tree and leaf order and gets
/// the same word.
#[test]
fn rust_recompiles_the_oracle_word_gate_for_gate() {
    let fixture = load_fixture();
    let mut worst_angle = 0.0_f64;
    let mut worst_angle_case = String::new();
    let mut worst_reconstruction = 0.0_f64;
    for case in &fixture.cases {
        let graph = graph_of(case);
        let target = RotationTarget::from_rows(case.target.clone()).unwrap();
        let tree = SpanningTree::new(
            &graph,
            case.tree_edges.iter().map(|&[a, b]| (a, b)).collect(),
        )
        .unwrap();
        let order = LeafOrder::new(&tree, case.leaf_order.clone()).unwrap();

        // The oracle's default plan is the one this crate reaches on its own.
        assert_eq!(
            graph.bfs_spanning_tree(0).unwrap(),
            tree,
            "{}: default tree disagrees",
            case.name
        );
        assert_eq!(
            tree.deterministic_leaf_order().unwrap(),
            order,
            "{}: default leaf order disagrees",
            case.name
        );

        let certificate = compile_on_tree(&target, &graph, &tree, &order).unwrap();
        assert_eq!(
            certificate.gates(),
            compile(&target, &graph).unwrap().gates()
        );
        assert_eq!(certificate.gate_count(), case.gate_count);
        assert_eq!(certificate.gate_count(), case.n * (case.n - 1) / 2);
        assert_eq!(certificate.gate_count(), case.schedule.len());

        for (index, (mine, theirs)) in certificate.gates().iter().zip(&case.schedule).enumerate() {
            assert_eq!(
                (mine.left, mine.right),
                (theirs.i, theirs.j),
                "{} gate {index}: plane disagrees",
                case.name
            );
            assert!(
                graph.edge_between(mine.left, mine.right).is_some(),
                "{} gate {index}: not on an authored edge",
                case.name
            );
            let delta = (mine.theta - theirs.theta).abs();
            if delta > worst_angle {
                worst_angle = delta;
                worst_angle_case = format!("{} gate {index}", case.name);
            }
        }
        assert!(certificate.reconstruction_error_fro() < 1.0e-11);
        worst_reconstruction = worst_reconstruction.max(certificate.reconstruction_error_fro());
    }
    println!(
        "recompile: worst |dtheta| {worst_angle:e} ({worst_angle_case}); \
         worst reconstruction {worst_reconstruction:e}"
    );
    // Observed worst is ~4e-14. The two implementations are not bit-identical
    // and cannot be: the oracle applies each rotation as a full dense
    // `G @ reduced` matmul through BLAS, while this crate updates the two
    // affected rows directly, so the accumulated rounding differs. The bound
    // is set two orders above the observed worst to survive a different BLAS
    // or libm, and three orders below anything that could reorder the word.
    assert!(
        worst_angle <= 1.0e-11,
        "worst angle disagreement {worst_angle:e} at {worst_angle_case}"
    );
}

/// Rust re-times the word and matches the oracle's thermodynamic receipt.
#[test]
fn rust_retimes_the_oracle_word() {
    let fixture = load_fixture();
    let mut worst_length = 0.0_f64;
    let mut worst_cost = 0.0_f64;
    let mut worst_segment = 0.0_f64;
    let mut zero_length_cases = 0usize;
    for case in &fixture.cases {
        let graph = graph_of(case);
        let target = RotationTarget::from_rows(case.target.clone()).unwrap();
        let certificate = compile(&target, &graph).unwrap();
        let metric = FrictionMetric::resolve(certificate.gates(), &graph).unwrap();
        let schedule = thermodynamic_schedule(certificate.gates(), &metric, case.duration).unwrap();

        if case.thermodynamic_length == 0.0 {
            // Documented deviation: for a zero-length word this crate emits
            // tau = 0 everywhere and an empty executable schedule, where the
            // reference spreads the duration uniformly over gates that do
            // nothing.
            zero_length_cases += 1;
            assert_eq!(schedule.thermodynamic_length(), 0.0);
            assert_eq!(schedule.minimum_quadratic_cost(), 0.0);
            assert!(schedule.executable_indices().is_empty());
            assert!(schedule.segment_durations().iter().all(|tau| *tau == 0.0));
            assert!(
                case.segment_durations.iter().all(|tau| *tau > 0.0),
                "{}: the reference is expected to spread the duration here",
                case.name
            );
            continue;
        }

        let length_delta = relative(schedule.thermodynamic_length(), case.thermodynamic_length);
        let cost_delta = relative(
            schedule.minimum_quadratic_cost(),
            case.minimum_quadratic_cost,
        );
        worst_length = worst_length.max(length_delta);
        worst_cost = worst_cost.max(cost_delta);
        assert!(
            length_delta <= 1.0e-12,
            "{}: thermodynamic length {} vs oracle {}",
            case.name,
            schedule.thermodynamic_length(),
            case.thermodynamic_length
        );
        assert!(
            cost_delta <= 1.0e-12,
            "{}: predicted cost disagrees",
            case.name
        );

        assert_eq!(
            schedule.segment_durations().len(),
            case.segment_durations.len()
        );
        for (mine, theirs) in schedule
            .segment_durations()
            .iter()
            .zip(case.segment_durations.iter())
        {
            let delta = (mine - theirs).abs() / case.duration;
            worst_segment = worst_segment.max(delta);
            assert!(
                delta <= 1.0e-12,
                "{}: segment duration disagrees",
                case.name
            );
        }
        assert!(case.constant_speed_residual <= 1.0e-12);
        assert!(schedule.constant_speed_residual() <= 1.0e-12);
    }
    assert!(zero_length_cases >= 1, "no identity case in the fixture");
    println!(
        "retime: worst relative length {worst_length:e}, cost {worst_cost:e}, \
         segment {worst_segment:e}"
    );
}

fn relative(actual: f64, expected: f64) -> f64 {
    (actual - expected).abs() / expected.abs().max(1.0)
}
